import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as t,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Cursor glossary","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/cursor/cursor-glossary.md","filePath":"products/ai-coding/cursor/cursor-glossary.md","lastUpdated":1787046041000}'),a={name:"products/ai-coding/cursor/cursor-glossary.md"};function n(d,e,c,i,l,p){return t(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="cursor-glossary" tabindex="-1">Cursor glossary <a class="header-anchor" href="#cursor-glossary" aria-label="Permalink to &quot;Cursor glossary&quot;">​</a></h1><p>Explanation: what a concept is, why it exists, and what it is easy to confuse with. How to configure it: <a href="./cursor-cheatsheet.html">cheatsheet</a>. How to click it: <a href="./cursor.html">tutorial</a>.</p><h2 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌──────────────┐</span></span>
<span class="line"><span>                    │  model+tools │</span></span>
<span class="line"><span>                    └──────┬───────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>              ┌────────────┼────────────┐</span></span>
<span class="line"><span>              │            │            │</span></span>
<span class="line"><span>         ┌────┴────┐  ┌───┴────┐  ┌────┴────┐</span></span>
<span class="line"><span>         │  Rules  │  │ Skills │  │   MCP   │</span></span>
<span class="line"><span>         │ AGENTS  │  │Commands│  │ (ext.)  │</span></span>
<span class="line"><span>         └────┬────┘  └───┬────┘  └────┬────┘</span></span>
<span class="line"><span>              │           │            │</span></span>
<span class="line"><span>              └─────┬─────┴──────┬─────┘</span></span>
<span class="line"><span>                    │            │</span></span>
<span class="line"><span>              ┌─────┴─────┐ ┌────┴────┐</span></span>
<span class="line"><span>              │   Agent   │ │  Hooks  │</span></span>
<span class="line"><span>              │ Ask/Plan/ │ └─────────┘</span></span>
<span class="line"><span>              │ Debug/Tab │</span></span>
<span class="line"><span>              └─────┬─────┘</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>         ┌──────────┼──────────┐</span></span>
<span class="line"><span>         │                     │</span></span>
<span class="line"><span>   ┌─────┴─────┐        ┌──────┴──────┐</span></span>
<span class="line"><span>   │ Subagents │        │ Cloud/Bugbot│</span></span>
<span class="line"><span>   │  / CLI    │        │             │</span></span>
<span class="line"><span>   └───────────┘        └─────────────┘</span></span></code></pre></div><p>Rules / <code>AGENTS.md</code> are the standing brief. Skills / Commands are on-demand workflows. MCP turns external systems into tools. Hooks sit on the loop and do not rely on the model remembering. The Agent picks tools inside those constraints. Subagents move noisy work into another window. Bugbot and Cloud sit on the repo / PR axis.</p><hr><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p><strong>What:</strong> Persistent instructions prepended to model context. Official wording: models do not keep memory across completions; rules supply reusable prompt-level context.</p><p><strong>Why:</strong> Without them you restate “use pnpm” every thread. With them the team commits the convention.</p><p><strong>Four triggers:</strong> Always / glob / description (“apply intelligently”) / <code>@</code> only. Truth table: <a href="./cursor-cheatsheet.html#rules-frontmatter">cheatsheet</a>.</p><p><strong>Versus AGENTS.md:</strong></p><table tabindex="0"><thead><tr><th></th><th>Rules (<code>.mdc</code>)</th><th>AGENTS.md</th></tr></thead><tbody><tr><td>Format</td><td>YAML frontmatter + Markdown</td><td>Plain Markdown</td></tr><tr><td>Trigger</td><td>Four modes</td><td>Present as project instructions</td></tr><tr><td>Best for</td><td>Path-scoped, needs metadata</td><td>Simple, portable, human-readable</td></tr></tbody></table><p>A plain <code>.md</code> under <code>.cursor/rules</code> is <strong>ignored</strong>. Official advice: use <code>AGENTS.md</code> if you want plain markdown.</p><p><strong>Precedence:</strong> Team → Project → User. Merged; earlier source wins.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/rules" target="_blank" rel="noreferrer">Rules</a></p><hr><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to &quot;AGENTS.md&quot;">​</a></h2><p><strong>What:</strong> A normal Markdown file at the repo root (or a subdirectory) written for agents. No <code>description</code> / <code>globs</code> / <code>alwaysApply</code>.</p><p><strong>Why:</strong> One file can serve Cursor, Claude Code, Codex, and anything else that reads <code>AGENTS.md</code>. Rules globs are stronger but Cursor-specific.</p><p><strong>Role:</strong> Small repos can stop here. Larger ones: root <code>AGENTS.md</code> for globals, <code>.cursor/rules/*.mdc</code> per language or folder.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/rules" target="_blank" rel="noreferrer">Rules · AGENTS.md</a></p><hr><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p><strong>What:</strong> An Agent Skills directory: <code>SKILL.md</code> plus optional <code>scripts/</code>, <code>references/</code>, <code>assets/</code>. Discovered at startup. The agent uses <code>description</code> to decide relevance; you can also type <code>/skill-name</code>.</p><p><strong>Why:</strong> Always-on rules consume the window every turn. Long runbooks should load on demand.</p><p><strong>Versus Commands:</strong> Commands run when you type <code>/</code>. Skills may auto-apply unless <code>disable-model-invocation: true</code>. Cursor 2.4 ships <code>/migrate-to-skills</code> for dynamic rules and slash commands.</p><p><strong>Built-ins</strong> (official table, not a product inventory): <code>/create-rule</code>, <code>/create-skill</code>, <code>/create-subagent</code>, <code>/review-bugbot</code>, <code>/babysit</code>, and others. Recheck <a href="https://cursor.com/docs/skills" target="_blank" rel="noreferrer">Skills</a> before documenting a slash name.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/skills" target="_blank" rel="noreferrer">Skills</a></p><hr><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p><strong>What:</strong> Markdown in <code>.cursor/commands/</code>, <code>~/.cursor/commands/</code>, or Dashboard Team Commands. Listed when you type <code>/</code>.</p><p><strong>Why:</strong> Prompts you run many times a day with a fixed script (open a PR, apply an issue template) without packing a Skill.</p><p><strong>Status:</strong> Official page still says beta. Do not declare them removed.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/context/commands" target="_blank" rel="noreferrer">Commands</a></p><hr><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p><strong>What:</strong> Model Context Protocol. Transports: <code>stdio</code>, <code>SSE</code>, <code>Streamable HTTP</code>.</p><p><strong>Why:</strong> Without it you paste Figma JSON and Sentry traces into chat. With it the agent pulls live systems.</p><p><strong>Versus Hooks:</strong> MCP is a tool the agent can call. A hook is <em>your</em> script around a call. They stack: a hook can audit or block an MCP tool.</p><p><strong>Safety:</strong> Servers run code and call APIs as you. Official notes: trusted sources, least-privilege keys, read the source for anything important.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/mcp" target="_blank" rel="noreferrer">MCP</a></p><hr><h2 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;Hooks&quot;">​</a></h2><p><strong>What:</strong> Processes spawned on Agent / Tab / workspace events. JSON over stdin/stdout. They can observe, block, or change behavior.</p><p><strong>Why:</strong> Models will not reliably “always run prettier” or “never <code>DELETE</code> production.” Hooks keep policy outside the prompt.</p><p><strong>Three families:</strong> Agent hooks, Tab hooks, <code>workspaceOpen</code>. Cloud agents run command-based <strong>project</strong> hooks only (no home-dir hooks, no prompt-based hooks). Reasons are in the official Hooks page (read-only early turns, no IDE session boundary, etc.).</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/hooks" target="_blank" rel="noreferrer">Hooks</a></p><hr><h2 id="subagents" tabindex="-1">Subagents <a class="header-anchor" href="#subagents" aria-label="Permalink to &quot;Subagents&quot;">​</a></h2><p><strong>What:</strong> Specialists the parent can spawn. Own context window. Foreground (blocking) or background (parallel).</p><p><strong>Why:</strong> Official built-ins came from conversations that blew the window:</p><table tabindex="0"><thead><tr><th>Subagent</th><th>Job</th><th>Why isolated</th></tr></thead><tbody><tr><td>Explore</td><td>Search and analyze</td><td>Huge intermediate output; faster model; many parallel searches</td></tr><tr><td>Bash</td><td>Shell series</td><td>Noisy logs</td></tr><tr><td>Browser</td><td>Browser MCP</td><td>DOM / screenshots</td></tr></tbody></table><p><strong>Versus Skills</strong> (official table): isolation, parallelism, multi-step expertise → subagent. One-shot repeatable action → skill.</p><p><strong>Cost:</strong> Each subagent burns its own tokens. Simple work is often faster on the parent.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/subagents" target="_blank" rel="noreferrer">Subagents</a></p><hr><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><p><strong>What:</strong> Constraints on one agent, not four products.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Constraint</th></tr></thead><tbody><tr><td>Agent</td><td>May edit and run commands</td></tr><tr><td>Ask</td><td>Read-only (changelog: search tools included; <code>@Codebase</code> tool gone)</td></tr><tr><td>Plan</td><td>Research, questions, editable plan; code after approval</td></tr><tr><td>Debug</td><td>Hypotheses → instrumentation → you reproduce → evidence</td></tr></tbody></table><p><strong>Why:</strong> Default Agent wants to write code. Plan separates <em>what</em> from <em>how</em>. Debug stops unmotivated edits. Ask keeps an orientation thread from touching files.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/agent/overview" target="_blank" rel="noreferrer">Overview</a>, <a href="https://cursor.com/docs/agent/plan-mode" target="_blank" rel="noreferrer">Plan</a>, <a href="https://cursor.com/docs/agent/debug-mode" target="_blank" rel="noreferrer">Debug</a></p><hr><h2 id="tab" tabindex="-1">Tab <a class="header-anchor" href="#tab" aria-label="Permalink to &quot;Tab&quot;">​</a></h2><p><strong>What:</strong> A completion model. Accept (<code>Tab</code>) and reject (<code>Esc</code>) become signal for later suggestions.</p><p><strong>Why:</strong> A full agent turn is the wrong tool for “change the next three lines.” Tab uses recent edits, lints, and accepted suggestions.</p><p><strong>Not Chat.</strong> No tool loop. It does not treat your Rules folder as a task brief.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/tab/overview" target="_blank" rel="noreferrer">Tab</a></p><hr><h2 id="bugbot" tabindex="-1">Bugbot <a class="header-anchor" href="#bugbot" aria-label="Permalink to &quot;Bugbot&quot;">​</a></h2><p><strong>What:</strong> A service that reviews a PR diff (or the local diff <code>/review-bugbot</code> sees). It looks for bugs, security issues, and quality problems, then comments with fix ideas.</p><p><strong>Why:</strong> Humans fatigue on large AI diffs. Bugbot reruns on each push and can follow <code>.cursor/BUGBOT.md</code> / team rules.</p><p><strong>Not Debug Mode.</strong> Debug instruments your workspace. Bugbot reads a diff; it does not boot your app. The old overview matrix called Bugbot a “runtime debugger.” That was wrong.</p><p><strong>Autofix:</strong> Official feature name. It spawns a Cloud Agent to patch findings. There is no separate 2026 product page titled Fixer.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/bugbot" target="_blank" rel="noreferrer">Bugbot</a></p><hr><h2 id="checkpoints" tabindex="-1">Checkpoints <a class="header-anchor" href="#checkpoints" aria-label="Permalink to &quot;Checkpoints&quot;">​</a></h2><p><strong>What:</strong> Automatic snapshots of files the agent is about to change. Preview and Restore from the timeline.</p><p><strong>Why:</strong> Exploration and large refactors need an undo that is not “one more prompt.” Checkpoints are not git commits and not Plan files.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/agent/overview" target="_blank" rel="noreferrer">Agent Overview · Checkpoints</a></p><hr><h2 id="codebase-indexing" tabindex="-1">Codebase Indexing <a class="header-anchor" href="#codebase-indexing" aria-label="Permalink to &quot;Codebase Indexing&quot;">​</a></h2><p><strong>What:</strong> The repo is chunked at function/class granularity, embedded, and searched by meaning. “Where is the top nav?” can hit <code>header.tsx</code>.</p><p><strong>Why:</strong> grep misses synonyms. Official claim: embeddings are computed at index time, so agent search is faster and cheaper.</p><p><strong>Privacy (official):</strong> paths encrypted; source not stored in plaintext long-term; processed in memory while indexing. Defaults exclude <code>.gitignore</code> / <code>.cursorignore</code>. Semantic search is available around <strong>80%</strong> index completion. Idle indexes are deleted after about six weeks.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/context/semantic-search" target="_blank" rel="noreferrer">Semantic search</a></p><hr><h2 id="privacy-mode" tabindex="-1">Privacy Mode <a class="header-anchor" href="#privacy-mode" aria-label="Permalink to &quot;Privacy Mode&quot;">​</a></h2><p><strong>What:</strong> A governance switch. When on, Cursor and model providers <strong>do not train on your code</strong>. On by default for Enterprise teams.</p><p><strong>Why:</strong> Two exits exist: LLM requests, and (optional) encrypted repo copies for Cloud Agents. Privacy Mode is about training / retention promises. It is <strong>not</strong> “code never leaves the machine.”</p><p><strong>Cloud Agents:</strong> Officially the only feature that requires Cursor to store code. If policy forbids storage, leave Cloud Agents off. Everything else still works.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/enterprise/privacy-and-data-governance" target="_blank" rel="noreferrer">Privacy and Data Governance</a></p><hr><h2 id="cloud-agents" tabindex="-1">Cloud Agents <a class="header-anchor" href="#cloud-agents" aria-label="Permalink to &quot;Cloud Agents&quot;">​</a></h2><p><strong>What:</strong> Agents on isolated VMs. They clone, branch, work, and open PRs. Start from the editor Cloud dropdown, <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a>, <a href="https://cursor.com/docs/cloud-agent/mobile" target="_blank" rel="noreferrer">mobile</a>, Slack / GitHub / Linear <code>@cursor</code>, or a CLI message prefixed with <code>&amp;</code>.</p><p><strong>Former name:</strong> Background Agents (official Naming History). Do not document them as two products.</p><p><strong>Why:</strong> Work that should not occupy the local window: drive-by bugs, tests, docs, many parallel runs. Cousins: Claude remote / Dispatch, Gemini Jules.</p><p><strong>Versus local subagents:</strong> Local children use your machine and local MCP. Cloud uses team MCP and the cloud environment.</p><p><strong>Versus Bugbot:</strong> Cloud <em>edits</em> a repo. Bugbot <em>reviews</em> a PR diff. Autofix is the bridge.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/cloud-agent" target="_blank" rel="noreferrer">Cloud Agent</a>, <a href="https://cursor.com/docs/cloud-agent/setup" target="_blank" rel="noreferrer">Setup</a>, <a href="https://cursor.com/blog/agent-best-practices" target="_blank" rel="noreferrer">agent-best-practices</a>. Tutorial: <a href="./cloud-agents.html">Cloud Agents</a>.</p><hr><h2 id="cursor-cli" tabindex="-1">Cursor CLI <a class="header-anchor" href="#cursor-cli" aria-label="Permalink to &quot;Cursor CLI&quot;">​</a></h2><p><strong>What:</strong> Official terminal entry. The binary is <strong><code>agent</code></strong>. Interactive session or <code>agent -p</code> for headless / CI. Same Agent / Ask / Plan modes. Loads <code>.cursor/rules</code>, <code>AGENTS.md</code>, and <code>CLAUDE.md</code>.</p><p><strong>Why:</strong> You are already in SSH / tmux / CI and should not open a GUI just to reuse the same rules. This is another surface of the same agent, not a third model.</p><p><strong>Versus editor / Cloud:</strong> The editor has Tab and Inline Edit; the CLI does not. Cloud runs on an isolated VM; the CLI edits the current working tree unless you pass <code>--worktree</code>. Prefix a message with <code>&amp;</code> to hand off to Cloud.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/cli/overview" target="_blank" rel="noreferrer">CLI Overview</a>, <a href="https://cursor.com/docs/cli/installation" target="_blank" rel="noreferrer">Installation</a>, <a href="https://cursor.com/docs/cli/headless" target="_blank" rel="noreferrer">Headless</a>. Tutorial: <a href="./cursor-cli.html">Cursor CLI</a>.</p><hr><h2 id="design-mode" tabindex="-1">Design Mode <a class="header-anchor" href="#design-mode" aria-label="Permalink to &quot;Design Mode&quot;">​</a></h2><p><strong>What:</strong> Visual prompting in the browser inside the Agents Window. Click an element, multi-select, draw on a frozen viewport frame, or speak. Toggle <code>Cmd+Shift+D</code>.</p><p><strong>Why:</strong> UI changes are spatial. The agent gets element identity (xpath, component, computed styles, fiber props) plus a screenshot, not just a sentence.</p><p><strong>Versus Claude Design:</strong> This is an overlay on <em>your running app</em>. <a href="./../claude/claude-design.html">Claude Design</a> is a standalone brand-aware canvas.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/agent/design-mode" target="_blank" rel="noreferrer">Design Mode</a>. Tutorial: <a href="./design-mode.html">Design Mode</a>.</p><hr><h2 id="origin" tabindex="-1">Origin <a class="header-anchor" href="#origin" aria-label="Permalink to &quot;Origin&quot;">​</a></h2><p><strong>What:</strong> Cursor&#39;s git forge (early beta). Host repos, mirror GitHub, browse / search at <code>cursor.com/codebase</code>, open and merge PRs. The CLI binary is <strong><code>origin</code></strong>, not <code>agent</code>.</p><p><strong>Why:</strong> You want Cursor-hosted storage and PRs, not only review comments on GitHub.</p><p><strong>Not Rules.</strong> Claiming a <strong>codebase name</strong> enables it. Pro / Teams / Enterprise only. Follows the namespace owner&#39;s Privacy Mode. Legacy privacy cannot enable it.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/origin" target="_blank" rel="noreferrer">Origin</a>. Tutorial: <a href="./origin.html">Origin</a>.</p><hr><h2 id="security-agents" tabindex="-1">Security Agents <a class="header-anchor" href="#security-agents" aria-label="Permalink to &quot;Security Agents&quot;">​</a></h2><p><strong>What:</strong> Two Cursor-managed agents on Automations: <strong>Security Reviewer</strong> (PR / MR) and <strong>Vulnerability Scanner</strong> (cron). They require Cloud Agents. Local skill: <code>/review-security</code> (Cursor 3.7+; CLI coming soon).</p><p><strong>Why:</strong> Dedicated security gate and at-rest scan, billed to the <strong>team usage pool</strong> under a shared service account.</p><p><strong>Versus Bugbot:</strong> Bugbot comments on a general PR diff. Security Agents are a separate managed family. PR Routing can read both.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/security-agents" target="_blank" rel="noreferrer">Security Agents</a>. Tutorial: <a href="./security-agents.html">Security Agents</a>.</p><hr><h2 id="pr-routing-approval" tabindex="-1">PR Routing &amp; Approval <a class="header-anchor" href="#pr-routing-approval" aria-label="Permalink to &quot;PR Routing &amp; Approval&quot;">​</a></h2><p><strong>What:</strong> Automations agent that assigns reviewers from ownership / history and can approve low-risk PRs. Exact policy file: <code>APPROVAL_POLICY.md</code>. Optional routing: <code>.cursor/approval-policies/ROUTING.md</code>.</p><p><strong>Why:</strong> Route the right humans; auto-approve only where policy allows. It does <strong>not</strong> replace a full code review.</p><p><strong>Gotcha:</strong> Wrong filename is ignored. A PR that edits its own policy cannot use the new text to relax that same PR.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/approval-agents" target="_blank" rel="noreferrer">PR Routing &amp; Approval</a>. Tutorial: <a href="./pr-routing.html">PR Routing</a>.</p><hr><h2 id="cursor-sdk" tabindex="-1">Cursor SDK <a class="header-anchor" href="#cursor-sdk" aria-label="Permalink to &quot;Cursor SDK&quot;">​</a></h2><p><strong>What:</strong> Call the same agent from your process. TypeScript <code>@cursor/sdk</code> (Node 22.13+), Python <code>cursor-sdk</code> (3.10+), other languages via the <strong>SDK Bridge</strong>. Runtime is <code>local</code> or <code>cloud</code>; local is the loop + filesystem, <strong>not</strong> a local model.</p><p><strong>Why:</strong> CI bots, triage workers, in-product agents, orchestrators. Same pricing / Privacy Mode as IDE and Cloud; spend tagged <strong>SDK</strong>.</p><p><strong>Keys:</strong> user or service-account. Team Admin API keys are not supported yet.</p><p><strong>Docs:</strong> <a href="https://cursor.com/docs/sdk/typescript" target="_blank" rel="noreferrer">TypeScript</a>, <a href="https://cursor.com/docs/sdk/python" target="_blank" rel="noreferrer">Python</a>, <a href="https://cursor.com/docs/sdk/bridge" target="_blank" rel="noreferrer">Bridge</a>. Tutorial: <a href="./cursor-sdk.html">Cursor SDK</a>.</p>`,135)])])}const f=o(a,[["render",n]]);export{b as __pageData,f as default};
